'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrcv = require( './../../cv/lib/main' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes the coefficient of variation (CV), ignoring NaN values.
*
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnancv();
*
* var cv = accumulator();
* // returns null
*
* cv = accumulator( 2.0 );
* // returns 0.0
*
* cv = accumulator( NaN );
* // returns 0.0
*
* cv = accumulator( 1.0 );
* // returns ~0.47
*
* cv = accumulator();
* // returns ~0.47
*/
function incrnancv() {
    var cv = incrcv();

    return function accumulator( x ) {
        if ( arguments.length === 0 ) {
            return cv();
        }
        if ( isnan( x ) ) {
            return cv();
        }
        return cv( x );
    };
}


// EXPORTS //

module.exports = incrnancv;
